import { AggregateRoot, DomainError, notImplemented } from '@agentic-ddd/core';
import { AgentEntity, AgentMethod, Invariant } from '@agentic-ddd/decorators';
import { TaskCreated, TaskCompleted } from './task.events';

@AgentEntity({ description: 'Tarefa com título e ciclo de vida pendente ou concluído.', states: ['pending', 'completed'] })
@Invariant({ id: 'titulo-obrigatorio', text: 'Toda tarefa precisa de título não vazio.' })
export class Task extends AggregateRoot<string> {
  #status: 'pending' | 'completed' = 'pending';
  private constructor(id: string, readonly title: string) { super(id); }
  get status(): 'pending' | 'completed' { return this.#status; }

  @AgentMethod({ description: 'Cria uma tarefa pendente e remove espaços nas extremidades do título.', emits: [TaskCreated] })
  static create(id: string, title: string): Task {
    const normalizedTitle = title.trim(); if (!normalizedTitle) throw new DomainError('TASK_TITLE_REQUIRED', 'Task title is required'); const task = new Task(id, normalizedTitle); task.record(new TaskCreated({ taskId: id, title: normalizedTitle })); return task;













  }

  @AgentMethod({ description: 'Conclui uma tarefa pendente; repetição falha com TASK_ALREADY_COMPLETED.', transition: { from: ['pending'], to: 'completed' }, emits: [TaskCompleted] })
  complete(): void {
    if (this.#status === 'completed') throw new DomainError('TASK_ALREADY_COMPLETED', 'Task is already completed'); this.#status = 'completed'; this.record(new TaskCompleted({ taskId: this.id }));













  }
}

import { describe, expect, it } from 'bun:test';
import { DomainError } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';

describe('Task.complete', () => {
  it(covers(['method:Task.complete', 'criterion:0001/conclusao'], 'conclui pending, registra TaskCompleted e rejeita repeticao'), () => {
    const task = Task.create('t1', 'tarefa');

    task.pullEvents();
    task.complete();

    expect(task.status).toBe('completed');
    const events = task.pullEvents();
    expect(events).toHaveLength(1);
    expect(events[0]).toBeInstanceOf(TaskCompleted);
    expect(events[0]!.payload).toEqual({ taskId: 't1' });

    try {
      task.complete();
      throw new Error('expected DomainError');
    } catch (error) {
      expect(error).toBeInstanceOf(DomainError);
      expect((error as DomainError).code).toBe('TASK_ALREADY_COMPLETED');
    }
  });
});
